cssCode:
.book-wrap {
  perspective: 1000px; width: 160px; height: 230px;
  display: flex; align-items: center; justify-content: center;
}
.book {
  width: 100%; height: 100%; position: relative;
  transform-style: preserve-3d; transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  cursor: pointer; box-shadow: 20px 20px 40px rgba(0,0,0,0.5);
  border-radius: 5px 15px 15px 5px;
}
.book-wrap:hover .book { transform: rotateY(-20deg) scale(1.05); }
.page {
  position: absolute; width: 100%; height: 100%;
  border-radius: 5px 15px 15px 5px; font-family: sans-serif;
  display: flex; align-items: center; justify-content: center;
}
.page-back { background: #e0e0e0; transform: translateZ(-5px); }
.page-front {
  background: linear-gradient(135deg, #ff007f, #6c63ff); color: #fff;
  font-weight: 900; font-size: 24px; z-index: 2;
  transform-origin: left center; transition: transform 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform: translateZ(5px); box-shadow: inset 5px 0 10px rgba(0,0,0,0.2);
}
.book-wrap:hover .page-front {
  transform: rotateY(-140deg) translateZ(5px);
  box-shadow: 5px 5px 20px rgba(0,0,0,0.4);
}
.page-content {
  position: absolute; width: 100%; height: 100%;
  background: #fff; border-radius: 5px 15px 15px 5px;
  color: #333; display: flex; flex-direction: column; align-items: center; justify-content: center;
  font-weight: bold; font-family: sans-serif; padding: 20px; box-sizing: border-box; text-align: center;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'book-wrap';

const book = document.createElement('div');
book.className = 'book';

const content = document.createElement('div');
content.className = 'page-content';
content.innerHTML = '<span style="font-size:30px;">📖</span><p style="font-size:12px; margin-top:10px;">Premium Content Revealed!</p>';

const pageBack = document.createElement('div');
pageBack.className = 'page page-back';

const pageFront = document.createElement('div');
pageFront.className = 'page page-front';
pageFront.innerText = 'OPEN';

book.appendChild(content);
book.appendChild(pageBack);
book.appendChild(pageFront);
wrap.appendChild(book);
c.appendChild(wrap);
